package com.sourcetoolkit.app;
import android.app.*;import android.content.Intent;import android.os.Bundle;import android.net.Uri;import android.view.*;import android.widget.*;import android.graphics.Typeface;import androidx.documentfile.provider.DocumentFile;import java.io.*;
public class ModEditorActivity extends Activity{
 DocumentFile mod;LinearLayout list;int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xFF0B0E10);getWindow().setNavigationBarColor(0xFF0B0E10);Uri u=Uri.parse(getIntent().getStringExtra("uri"));mod=DocumentFile.fromTreeUri(this,u);if(mod==null)mod=DocumentFile.fromSingleUri(this,u);render();}
 void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(18),dp(18),dp(12));root.setBackgroundColor(0xFF0B0E10);setContentView(root);TextView h=new TextView(this);h.setText("MOD EDITOR");h.setTextSize(20);h.setTextColor(0xFFE6EAED);root.addView(h);TextView sub=new TextView(this);sub.setText(mod.getName());sub.setTextColor(0xFF2D9CFF);root.addView(sub);LinearLayout actions=new LinearLayout(this);Button a=button("新建文件"),b=button("新建文件夹");actions.addView(a,new LinearLayout.LayoutParams(0,dp(42),1));actions.addView(b,new LinearLayout.LayoutParams(0,dp(42),1));root.addView(actions);a.setOnClickListener(v->create(false));b.setOnClickListener(v->create(true));ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));load();}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(0xFFE6EAED);b.setAllCaps(false);b.setBackgroundColor(0xFF12171B);return b;}
 void load(){list.removeAllViews();for(DocumentFile f:mod.listFiles()){TextView t=new TextView(this);t.setText((f.isDirectory()?"▸ ":"")+f.getName());t.setTextSize(14);t.setTextColor(0xFFE6EAED);t.setPadding(dp(10),dp(13),dp(8),dp(13));list.addView(t);View line=new View(this);line.setBackgroundColor(0xFF232B31);list.addView(line);t.setOnClickListener(v->{if(f.isDirectory()){Intent i=new Intent(this,ModFolderActivity.class);i.putExtra("uri",f.getUri().toString());startActivity(i);}else if(f.getName()!=null&&f.getName().toLowerCase().endsWith(".lua"))edit(f);});}}
 void create(boolean folder){EditText e=new EditText(this);e.setSingleLine(true);new AlertDialog.Builder(this).setTitle(folder?"新建文件夹":"新建文件").setView(e).setPositiveButton("创建",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty())return;if(folder)mod.createDirectory(n);else mod.createFile("text/plain",n);load();}).setNegativeButton("取消",null).show();}
 void edit(DocumentFile f){try{InputStream in=getContentResolver().openInputStream(f.getUri());ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();EditText e=new EditText(this);e.setText(out.toString("UTF-8"));e.setGravity(Gravity.TOP|Gravity.LEFT);e.setTypeface(Typeface.MONOSPACE);new AlertDialog.Builder(this).setTitle(f.getName()).setView(e).setPositiveButton("保存",(d,w)->{try{OutputStream o=getContentResolver().openOutputStream(f.getUri(),"wt");o.write(e.getText().toString().getBytes("UTF-8"));o.close();}catch(Exception ex){Toast.makeText(this,"保存失败",0).show();}}).setNegativeButton("取消",null).show();}catch(Exception ex){Toast.makeText(this,"读取失败",0).show();}}
}